+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+const promptBuilder = new PromptBuilder({identity: 'Test assistant.'});
+
+const throwingProvider = (thrown: unknown): AIProvider => ({
+  // eslint-disable-next-line require-yield
+  async *sendMessage(): AsyncGenerator<MessageChunk> {
+    throw thrown;
+  },
+  async generateStructured<T>(): Promise<T> {
+    throw new Error('unused');
+  },
+});
+
+const captureRejection = (call: Promise<unknown>): Promise<unknown> =>
+  call.then(() => Symbol('resolved')).catch((caught: unknown) => caught);
+
+const hasCauseProperty = (error: Error | undefined, passthrough: boolean): boolean => {
+  if (passthrough) return true;
+  return error instanceof Error ? 'cause' in error : false;
+};
+
+describe('onError coercion of arbitrary rejections', () => {
+  it('wraps non-Error rejections with cause and passes Error instances through', async () => {
+    const originalError = new Error('existing instance');
+    const cases: {kind: string; thrown: unknown; expectedMessage: string; sameInstance: boolean}[] = [
+      {kind: 'string', thrown: 'plain string boom', expectedMessage: 'plain string boom', sameInstance: false},
+      {kind: 'object', thrown: {code: 'WEIRD'}, expectedMessage: '{"code":"WEIRD"}', sameInstance: false},
+      {kind: 'undefined', thrown: undefined, expectedMessage: 'undefined', sameInstance: false},
+      {kind: 'bigint', thrown: BigInt(7), expectedMessage: '7', sameInstance: false},
+      {kind: 'error', thrown: originalError, expectedMessage: 'existing instance', sameInstance: true},
+    ];
+
+    const observed = [];
+    for (const {kind, thrown, expectedMessage, sameInstance} of cases) {
+      const seen: Error[] = [];
+      const hooks: OrchestratorHooks = {
+        onError: async (_session, error) => {
+          seen.push(error);
+        },
+      };
+      const session: ChatSession = {
+        sessionId: 's1',
+        userId: 'u1',
+        entries: [{role: 'user', content: 'hi', timestamp: SENT_AT}],
+      };
+      const orchestrator = createChatOrchestrator(throwingProvider(thrown), promptBuilder, undefined, {hooks});
+      const propagated = await captureRejection(orchestrator.processMessage(session));
+      const reported = seen[0];
+      observed.push({
+        kind,
+        calls: seen.length,
+        isError: reported instanceof Error,
+        messageMatches: reported?.message === expectedMessage,
+        sameInstance: Object.is(reported, thrown),
+        expectedSameInstance: sameInstance,
+        causeMatches: sameInstance ? true : Object.is(reported?.cause, thrown),
+        hasCauseKey: hasCauseProperty(reported, sameInstance),
+        propagatedMatches: Object.is(propagated, thrown),
+      });
+    }
+
+    const expected = cases.map(({kind, sameInstance}) => ({
+      kind,
+      calls: 1,
+      isError: true,
+      messageMatches: true,
+      sameInstance,
+      expectedSameInstance: sameInstance,
+      causeMatches: true,
+      hasCauseKey: true,
+      propagatedMatches: true,
+    }));
+    expect(observed).toEqual(expected);
+  });
+});
